edits.text:
:root {
    --bg-primary: #000000;
    --bg-secondary: #0a0a0a;
    --bg-card: #0f0f0f;
    --bg-hover: #151515;
    --text-primary: #e8f0e8;
    --text-secondary: #9ca3af;
    --accent-green: #39ff14;
    --accent-green-dim: #2ed60f;
    --accent-yellow: #ffd700;
    --accent-red: #ff3b3b;
    --accent-red-dim: #cc2f2f;
    --border-color: #1a1a1a;
    --shadow-color: rgba(0, 0, 0, 0.5);
    --success-glow: rgba(57, 255, 20, 0.3);
    --danger-glow: rgba(255, 59, 59, 0.3);
    --warning-glow: rgba(255, 215, 0, 0.3);
    /* Chart theming */
    --chart-text-color: #9ca3af;
    --chart-grid-color: rgba(255, 255, 255, 0.1);
}

[data-theme="light"] {
    --bg-primary: #f0f4f0;
    --bg-secondary: #ffffff;
    --bg-card: #fafafa;
    --bg-hover: #e8f5e8;
    --text-primary: #1a1f2e;
    --text-secondary: #4a5568;
    --accent-green: #2ed60f;
    --accent-green-dim: #27b00c;
    --accent-yellow: #cc9a00;
    --accent-red: #dc2626;
    --accent-red-dim: #b91c1c;
    --border-color: #d1d5db;
    --shadow-color: rgba(0, 0, 0, 0.1);
    --success-glow: rgba(46, 214, 15, 0.2);
    --danger-glow: rgba(220, 38, 38, 0.2);
    --warning-glow: rgba(204, 154, 0, 0.2);
    --chart-text-color: #374151; /* higher contrast for light theme */
    --chart-grid-color: rgba(0, 0, 0, 0.12);
}

* { 
    margin: 0; 
    padding: 0; 
    box-sizing: border-box; 
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background: var(--bg-primary);
    color: var(--text-primary);
    min-height: 100vh;
    margin: 0;
    overflow-x: hidden;
    position: relative;
}

body::before {
    content: '';
    position: fixed;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: 
        radial-gradient(circle at 20% 50%, rgba(57, 255, 20, 0.08) 0%, transparent 50%),
        radial-gradient(circle at 80% 80%, rgba(57, 255, 20, 0.06) 0%, transparent 50%),
        radial-gradient(circle at 40% 20%, rgba(57, 255, 20, 0.05) 0%, transparent 50%);
    animation: backgroundGlow 15s ease-in-out infinite;
    pointer-events: none;
    z-index: 0;
}

@keyframes backgroundGlow {
    0%, 100% { 
        transform: translate(0, 0) scale(1);
        opacity: 0.4;
    }
    33% { 
        transform: translate(10%, 10%) scale(1.1);
        opacity: 0.6;
    }
    66% { 
        transform: translate(-10%, 5%) scale(0.95);
        opacity: 0.5;
    }
}

body > * {
    position: relative;
    z-index: 1;
}

/* Side Panel Navigation */
.side-panel {
    position: fixed;
    left: 0;
    top: 0;
    height: 100vh;
    width: 70px;
    background: rgba(10, 10, 10, 0.92);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border-right: 1px solid rgba(57, 255, 20, 0.2);
    box-shadow: 0 0 30px rgba(57, 255, 20, 0.1);
    display: flex;
    flex-direction: column;
    align-items: center;
    z-index: 9999;
    transition: all 0.3s ease;
}

.side-panel:hover {
    background: rgba(15, 15, 15, 0.8);
    box-shadow: 0 0 40px rgba(57, 255, 20, 0.2);
}

.panel-icon-strip {
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 2rem 0;
}

.panel-logo-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 50px;
    height: 50px;
    color: var(--accent-green);
    font-size: 2rem;
    animation: pulse-glow 3s ease-in-out infinite;
    cursor: pointer;
    transition: all 0.3s ease;
}

.panel-logo-icon:hover {
    transform: scale(1.1);
    filter: drop-shadow(0 0 20px var(--success-glow));
}

@keyframes pulse-glow {
    0%, 100% { filter: drop-shadow(0 0 5px var(--success-glow)); }
    50% { filter: drop-shadow(0 0 15px var(--success-glow)) drop-shadow(0 0 25px var(--success-glow)); }
}

/* Graphs Preview Grid */
.graphs-preview {
    position: fixed;
    left: 70px;
    top: 50%;
    transform: translateY(-50%) translateX(-100%);
    background: rgba(10, 10, 10, 0.92);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border: 1px solid rgba(57, 255, 20, 0.3);
    border-left: none;
