    border: none;
    padding: 10px 20px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 600;
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
    gap: 8px;
    box-shadow: 0 4px 12px var(--success-glow);
}

.timeline-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 16px var(--success-glow);
